[
  {
    "statement": "Opening forest canopies through clearing, coppicing, or thinning has mixed effects on butterfly and moth communities.",
    "citations": []
  },
  {
    "statement": "Clearing or opening patches in forests generally increases butterfly species richness and abundance.",
    "citations": [
      "3938"
    ]
  },
  {
    "statement": "Clearing or opening patches in forests can decrease moth species richness.",
    "citations": [
      "3938"
    ]
  },
  {
    "statement": "Studies found higher butterfly abundance and species richness in cleared patches compared to unmanaged forest.",
    "citations": [
      "3938"
    ]
  },
  {
    "statement": "Nineteen out of sixty-seven butterfly species of conservation concern benefited from small forest clearings.",
    "citations": [
      "3938"
    ]
  },
  {
    "statement": "Wider woodland rides had lower moth abundance than standard width rides or mature forest.",
    "citations": [
      "3938"
    ]
  },
  {
    "statement": "Coppicing woodland typically increases butterfly abundance and species richness compared to mature forest.",
    "citations": [
      "3939"
    ]
  },
  {
    "statement": "Coppicing woodland can potentially reduce macro-moth abundance compared to mature forest.",
    "citations": [
      "3939"
    ]
  },
  {
    "statement": "Coppiced woodlands supported a higher abundance of butterflies generally.",
    "citations": [
      "3939"
    ]
  },
  {
    "statement": "Coppiced woodlands supported a higher abundance of the heath fritillary butterfly specifically.",
    "citations": [
      "3939"
    ]
  },
  {
    "statement": "Coppiced woodlands supported a higher abundance of eastern eggar moth caterpillars.",
    "citations": [
      "3939"
    ]
  },
  {
    "statement": "Different aged coppice supported different butterfly and moth communities.",
    "citations": [
      "3939"
    ]
  },
  {
