    "citations": [
      "3939"
    ]
  },
  {
    "statement": "Thinning trees within forests increases both butterfly species richness and abundance.",
    "citations": [
      "3940"
    ]
  },
  {
    "statement": "Coniferous woodlands that had been thinned showed greater butterfly species richness and abundance compared to unmanaged woodland.",
    "citations": [
      "3940"
    ]
  },
  {
    "statement": "One study found that partially-cleared forest plots had higher butterfly species richness than closed-canopy forest.",
    "citations": [
      "3940"
    ]
  },
