[
  {
    "statement": "Evidence from US prairies shows different outcomes for butterfly populations between rotational burning and leaving unburned patches during prescribed fires.",
    "citations": []
  },
  {
    "statement": "Some rotational burning studies showed higher butterfly abundance on prairies burned 2-4 years ago compared to recently burned areas.",
    "citations": []
  },
  {
    "statement": "Other studies found rotational burning every 2-5 years resulted in higher butterfly abundance than unmanaged sites.",
    "citations": []
  },
  {
    "statement": "Some prairie specialist butterflies were less abundant under rotational burning.",
    "citations": []
  },
  {
    "statement": "Three fritillary species showed lower abundance in rotationally burned prairies compared to hayed or grazed prairies.",
    "citations": []
  },
  {
    "statement": "Studies found that Karner blue butterfly abundance increased over 2-3 years in prairies where unburned patches were left.",
    "citations": []
  },
  {
    "statement": "Six out of nine specialist butterfly species were more abundant in areas with unburned patches compared to sites without unburned patches.",
    "citations": []
  },
  {
    "statement": "The Karner blue butterflies actively used all 11 unburned patches surveyed within managed prairies.",
    "citations": []
  }
]

[
  {
    "statement": "Several actions are available to mitigate the negative impacts of artificial lighting on moth populations.",
    "citations": []
  },
  {
    "statement": "Evidence from multiple studies supports the use of shielded \"full cut-off\" lights.",
    "citations": []
  },
  {
    "statement": "Shielded \"full cut-off\" lights reduced the number of individual moths and moth species attracted to lights in a study in Slovenia.",
    "citations": [
      "3904"
    ]
  },
  {
    "statement": "Using low intensity lighting was effective at mitigating negative impacts on moths.",
    "citations": []
  },
  {
    "statement": "A study in Germany found that fewer moths were attracted to low intensity lights that emitted yellow light with little UV compared to higher intensity lights with broader spectra.",
    "citations": [
      "3902"
    ]
  },
  {
    "statement": "The use of 'warmer' lighting colors like red or yellow rather than other colors has the strongest evidence base for mitigating negative impacts on moths.",
    "citations": []
  },
  {
    "statement": "Five studies across Germany, the Netherlands, Slovenia, and the UK found that fewer individual moths and moth species were attracted to yellow, green, white, or red lights compared to UV, actinic, blue, or conventional metal halide lights.",
    "citations": [
      "3906"
    ]
  },
  {
    "statement": "Restricting the use of polarized light is an available action to mitigate negative impacts of artificial lighting on moths.",
    "citations": [
      "3903"
    ]
  },
  {
    "statement": "Minimizing road lighting is an available action to reduce insect attraction.",
    "citations": [
      "3852"
    ]
  },
  {
    "statement": "Restricting the timing of lighting to conserve natural light regimes is an available action.",
    "citations": [
      "3901"
    ]
  },
  {
    "statement": "Using glazing treatments to reduce light spill from buildings is an available action.",
    "citations": [
      "3905"
    ]
  },
  {
    "statement": "Using barriers or vegetation to block artificial light is an available action.",
    "citations": [
      "3618"
    ]
  },
  {
    "statement": "Limiting or prohibiting industrial and urban lighting at night is an available action.",
    "citations": [
      "2208"
    ]
  },
  {
    "statement": "Actions such as restricting polarized light, minimizing road lighting, restricting lighting times, using glazing treatments, using barriers, and limiting night lighting currently lack specific studies evaluating their effectiveness for moth conservation.",
    "citations": [
      "3903",
      "3852",
      "3901",
      "3905",
      "3618",
      "2208"
    ]
  }
]

[
  {
    "statement": "Evidence from 29 studies on butterfly translocation and captive-release programs shows mixed long-term success.",
    "citations": []
  },
  {
    "statement": "In 16 studies of translocation programs, 8 studies reported successful establishment with butterfly populations persisting for 2-12 years and increasing in abundance.",
    "citations": []
  },
  {
    "statement": "In 16 studies of translocation programs, 3 studies documented some butterfly populations persisting for 1-49 years while other populations died out within 0-7 years.",
    "citations": []
  },
  {
    "statement": "A review of UK and Irish butterfly translocations found only 25% of populations survived for more than 3 years.",
    "citations": []
  },
  {
    "statement": "A review of UK and Irish butterfly translocations found 38% of populations died out within 3 years.",
    "citations": []
  },
  {
    "statement": "A review of UK and Irish butterfly translocations found only 8% of populations survived for more than 10 years.",
    "citations": []
  },
  {
    "statement": "Large copper butterfly translocations survived for up to 38 years but ultimately required supplementation.",
    "citations": []
  },
  {
    "statement": "In 13 studies of captive-release programs, 6 studies reported successful establishment with butterfly populations persisting for 2-28 years and increasing in abundance.",
    "citations": []
  },
  {
    "statement": "In 13 studies of captive-release programs, 2 studies documented butterfly populations dying out 1-12 years after release.",
    "citations": []
  },
  {
    "statement": "Captive-released populations of the large copper butterfly either died out or required ongoing supplementation.",
    "citations": []
  },
  {
    "statement": "Captive-released populations of the belted beauty moth either died out or required ongoing supplementation.",
    "citations": []
  },
  {
    "statement": "A study found only 3 of 10 captive-bred barberry carpet moth populations successfully established.",
    "citations": []
  },
  {
    "statement": "At least one successfully established captive-bred barberry carpet moth population persisted for 5 years.",
    "citations": []
  },
  {
    "statement": "Captive-bred individuals showed lower survival rates compared to wild or translocated counterparts.",
    "citations": []
  },
  {
    "statement": "Evidence indicates some butterfly populations can be successfully re-established through translocation or captive-release methods.",
    "citations": []
  },
  {
    "statement": "The long-term success rates for re-establishing butterfly populations are generally low.",
    "citations": []
  },
  {
    "statement": "Many re-established butterfly populations require ongoing management and supplementation to persist beyond a few years.",
    "citations": []
  }
]

[
  {
    "statement": "Urban environments can support butterfly and moth populations through several key actions.",
    "citations": []
  },
  {
    "statement": "Planting parks, gardens and road verges with appropriate native species has been shown to increase species richness of butterflies and moths.",
    "citations": []
  },
  {
    "statement": "Studies have found greater richness of butterflies and moths in areas with native plants compared to mixed or non-native plantings.",
    "citations": []
  },
  {
    "statement": "Practising wildlife gardening by avoiding insecticides and herbicides has demonstrated higher butterfly abundance in urban gardens.",
    "citations": []
  },
  {
    "statement": "Altering mowing regimes on greenspaces and road verges to be less frequent or unmown increases both species richness and abundance of butterflies compared to regularly mown areas.",
    "citations": []
  },
  {
    "statement": "Protecting existing greenfield sites or undeveloped land within urban areas maintains higher butterfly species richness than developed urban parks.",
    "citations": []
  },
  {
    "statement": "Establishing green infrastructure such as green roofs can provide habitat for butterflies and moths.",
    "citations": []
  },
  {
    "statement": "Older green roofs that contain more nectar plant species support higher butterfly abundance.",
    "citations": []
  },
  {
    "statement": "Stopping herbicide use on pavements and road verges creates habitat corridors.",
    "citations": []
  },
  {
    "statement": "Restoring roadside prairies to replace non-native weed-dominated verges leads to greater butterfly abundance and species richness.",
    "citations": []
  },
  {
    "statement": "Restoring roadside prairies to replace non-native weed-dominated verges reduces butterfly mortality risk.",
    "citations": []
  }
]

[
  {
    "statement": "Based on studies in US forests, shelterwood harvesting shows better outcomes for moth diversity compared to clearcutting.",
    "citations": []
  },
  {
    "statement": "One controlled, before-and-after study found that macro-moth species richness was higher after shelterwood harvesting than after patch-cutting or clearcutting.",
    "citations": [
      "3871"
    ]
  },
  {
    "statement": "A controlled, before-and-after study found that macro-moth species richness after shelterwood harvesting was similar to richness in thinned and unharvested forests.",
    "citations": [
      "3871"
    ]
  },
  {
    "statement": "A replicated, controlled study found that moth species richness recovered faster after shelterwood harvesting than after group selection harvesting or clearcutting.",
    "citations": [
      "3871"
    ]
  },
  {
    "statement": "For selective logging, the results regarding moth diversity are more mixed.",
    "citations": []
  },
  {
    "statement": "A replicated, controlled, before-and-after study in the USA found that forests harvested by single tree selection had similar moth species richness to clearcut forests.",
    "citations": [
      "3867"
    ]
  },
  {
    "statement": "A replicated, controlled, before-and-after study in the USA found that forests harvested by single tree selection had lower moth species richness than unharvested forests.",
    "citations": [
      "3867"
    ]
  },
  {
    "statement": "A study found that forests managed by shelterwood harvesting had similar moth species richness to forests managed by single tree harvesting and clearcutting.",
    "citations": [
      "3871"
    ]
  },
  {
    "statement": "A study found that forests managed by shelterwood harvesting had lower moth species richness than unharvested forest.",
    "citations": [
      "3871"
    ]
  },
  {
    "statement": "One study found higher macro-moth species richness after thinning compared to patch-cutting or clearcutting.",
    "citations": [
      "3868"
    ]
  },
  {
    "statement": "One study found that macro-moth species richness after thinning was similar to the richness in unharvested forest.",
    "citations": [
      "3868"
    ]
  },
  {
    "statement": "Group selection harvesting showed similar moth species richness to clearcutting.",
    "citations": [
      "3868"
    ]
  },
  {
    "statement": "Group selection harvesting showed lower moth species richness than unharvested forest.",
    "citations": [
      "3868"
    ]
  },
  {
    "statement": "Evidence suggests that shelterwood harvesting and thinning maintain better moth diversity than clearcutting.",
    "citations": []
  },
  {
    "statement": "Evidence suggests that the results for selective logging's impact on moth diversity are more variable.",
    "citations": []
  },
  {
    "statement": "Evidence suggests that selective logging is often similar to clearcutting in terms of moth species richness.",
    "citations": []
  }
]

[
  {
    "statement": "Mechanical cutting or mowing of linear features like power lines and road verges generally increases butterfly species richness and abundance compared to unmanaged areas.",
    "citations": []
  },
  {
    "statement": "Optimal effects on butterfly species richness and abundance from mechanical cutting or mowing are observed 2-4 years after scrub and tree clearance.",
    "citations": []
  },
  {
    "statement": "Rotational mowing practices, such as mowing strips in alternate years or leaving rotational areas uncut, show greater species richness and abundance of butterflies compared to complete annual mowing.",
    "citations": []
  },
  {
    "statement": "Stopping herbicide use on road verges results in greater butterfly species richness and abundance compared to areas with unrestricted herbicide application.",
    "citations": []
  },
  {
    "statement": "Butterfly mortality risk is reduced on herbicide-restricted verges.",
    "citations": []
  },
  {
    "statement": "Less frequently mown or unmown road verges have higher butterfly species richness, abundance, and diversity than frequently mown areas.",
    "citations": []
  },
  {
    "statement": "Late summer mowing shows benefits for butterflies over mid-summer mowing.",
    "citations": []
  },
  {
    "statement": "Restoration and maintenance of species-rich grassland along verges with native wildflowers and larval food plants increases butterfly and moth species richness and abundance compared to non-native vegetation.",
    "citations": []
  },
  {
    "statement": "Wider road verges support higher butterfly species richness and abundance than narrow verges.",
    "citations": []
  }
]

[
  {
    "statement": "Documented effects of excluding herbivores on butterfly and moth populations show varying results depending on the herbivore type.",
    "citations": []
  },
  {
    "statement": "One UK study found that excluding grazing animals with fencing resulted in a higher density of pearl-bordered fritillary butterflies at fenced sites compared to unfenced sites.",
    "citations": []
  },
  {
    "statement": "Fencing to exclude deer, elk, pigs, sheep and large herbivores generally increased butterfly and moth abundance, according to ten studies across multiple countries.",
    "citations": []
  },
  {
    "statement": "Five of eight studies on vertebrate herbivore exclusion showed a higher abundance of butterflies, moths, caterpillars, and rare macro-moths in fenced areas.",
    "citations": []
  },
  {
    "statement": "Two studies found that excluding vertebrate herbivores had mixed effects on butterfly and moth populations, with outcomes depending on fire intensity and year.",
    "citations": []
  },
  {
    "statement": "One study found a similar abundance of butterflies and moths between fenced and unfenced areas.",
    "citations": []
  },
  {
    "statement": "Three studies found increased species richness for butterflies and macro-moths in fenced forest plots.",
    "citations": []
  },
  {
    "statement": "Two studies found mixed effects on the species richness of butterflies and macro-moths when herbivores were excluded.",
    "citations": []
  },
  {
    "statement": "A global systematic review found that reducing or removing grazing increased the abundance of butterflies and moths.",
    "citations": []
  },
  {
    "statement": "A global systematic review found that reducing or removing grazing did not affect the species richness of butterflies and moths.",
    "citations": []
  },
  {
    "statement": "Two studies on livestock management showed that cattle or horse grazing increased species richness compared to sheep grazing.",
    "citations": []
  },
  {
    "statement": "Eight of eleven studies found that reducing grazing intensity by lowering stocking density generally increased butterfly and moth abundance.",
    "citations": []
  },
  {
    "statement": "Five of eight studies showed greater species richness of butterflies and moths at lower stocking densities.",
    "citations": []
  },
  {
    "statement": "The practice of seasonal livestock removal showed mixed results on butterfly and moth populations.",
    "citations": []
  },
  {
    "statement": "Three studies found a higher abundance of butterflies and moths when cattle or sheep were removed during the summer or winter.",
    "citations": []
  },
  {
    "statement": "Three studies found a similar abundance of butterflies and moths between seasonally grazed and continuously grazed areas.",
    "citations": []
  }
]

[
  {
    "statement": "Evidence from wetland habitat restoration studies shows mixed effectiveness for butterfly conservation.",
    "citations": []
  },
  {
    "statement": "Wetland and floodplain restoration increased macroinvertebrate diversity, which includes butterflies and moths.",
    "citations": []
  },
  {
    "statement": "Restored wetland prairie showed a higher abundance of great copper butterfly eggs than degraded areas.",
    "citations": []
  },
  {
    "statement": "Restored wetland prairie showed lower egg and caterpillar survival for the great copper butterfly.",
    "citations": []
  },
  {
    "statement": "Adult butterflies used restored wetland and floodplain areas more than degraded sites.",
    "citations": []
  },
  {
    "statement": "For peatland restoration, restored mires had higher species richness and abundance of mire specialist butterflies compared to unrestored sites.",
    "citations": []
  },
  {
    "statement": "Restored peatland sites were similar to pristine mires in terms of butterfly species richness and abundance.",
    "citations": []
  },
  {
    "statement": "A negative impact of peatland restoration observed was lower large heath butterfly caterpillar survival where water levels had risen.",
    "citations": []
  },
  {
    "statement": "A negative impact of peatland restoration was reduced Alcon large blue butterfly occupancy at sites where water levels had been recently raised.",
    "citations": []
  }
]

[
  {
    "statement": "Prescribed burning in forests can increase butterfly species richness and abundance.",
    "citations": []
  },
  {
    "statement": "Coniferous forests restored by burning, often in combination with thinning, had higher species richness of butterflies than unburned forests.",
    "citations": []
  },
  {
    "statement": "Pine forests restored by burning had higher butterfly abundance than unburned forests.",
    "citations": []
  },
  {
    "statement": "The benefits of prescribed burning for butterfly populations appear to be most pronounced 1-2 years after burning.",
    "citations": []
  },
  {
    "statement": "Some studies show an increased abundance of specific species like Fender's blue caterpillars and eggs following a prescribed burn.",
    "citations": []
  },
  {
    "statement": "Prescribed burning has documented negative impacts on butterfly and moth populations.",
    "citations": []
  },
  {
    "statement": "The primary negative impact of prescribed fire on butterflies and moths is direct mortality during the fire event.",
    "citations": []
  },
  {
    "statement": "One study in Australia reported fewer Eltham copper caterpillars in the spring after selective burning of eucalyptus forest compared to before the burning.",
    "citations": []
  },
  {
    "statement": "Research on Fender's blue butterfly found that caterpillar survival was lower in prairie plots burned one year before compared to unburned plots.",
    "citations": []
  },
  {
    "statement": "Recently burned areas may have reduced survival rates for the early life stages of butterflies.",
    "citations": []
  },
  {
    "statement": "The timing of burning is a critical factor for its impact on butterfly and moth populations.",
    "citations": []
  },
  {
    "statement": "Early season burning increased caterpillar abundance, while late season burning did not have this benefit.",
    "citations": []
  },
  {
    "statement": "Leaving some areas unburned during prescribed burning operations can help mitigate negative impacts on butterfly and moth populations.",
    "citations": []
  },
  {
    "statement": "Karner blue butterflies increased in abundance over 2-3 years in areas where unburned patches were left.",
    "citations": []
  },
  {
    "statement": "Six out of nine specialist butterfly species studied were more abundant when unburned areas were retained during prescribed burns.",
    "citations": []
  }
