[
  {
    "statement": "Protecting greenfield sites or undeveloped land is a conservation action for urban butterfly and moth populations.",
    "citations": []
  },
  {
    "statement": "Greenfield sites and undeveloped land have shown higher species richness than urban parks.",
    "citations": []
  },
  {
    "statement": "Planting parks, gardens, and road verges with native species generally increases species richness and abundance.",
    "citations": []
  },
  {
    "statement": "Stopping pesticide use can result in higher butterfly abundance.",
    "citations": []
  },
  {
    "statement": "Restricting herbicide use can increase species richness and abundance.",
    "citations": []
  },
  {
    "statement": "Altering mowing regimes to reduce the frequency of mowing can improve species richness, diversity, and abundance.",
    "citations": []
  },
  {
    "statement": "Establishing green infrastructure, like green roofs, is a conservation action for urban butterfly and moth populations.",
    "citations": []
  },
  {
    "statement": "Green roofs are less effective for conservation than parks.",
    "citations": []
  },
  {
    "statement": "The effectiveness of green roofs for conservation increases when the green roofs are older, contain more nectar plant species, and cover larger areas.",
