    "citations": [
      "3932"
    ]
  },
  {
    "statement": "Ten of seventeen studies found higher butterfly abundance in sown wildflower strips compared to conventional margins or cropped areas.",
    "citations": [
      "3932"
    ]
  },
  {
    "statement": "Uncultivated margins show mixed results for their effectiveness for butterfly communities.",
    "citations": [
      "3981"
    ]
  },
  {
    "statement": "Some studies found uncultivated margins had higher species richness than cropped field edges.",
    "citations": [
      "3981"
    ]
  },
  {
    "statement": "Multiple studies demonstrated uncultivated margins had lower species richness and abundance compared to sown wildflower strips or grass and forb margins.",
    "citations": [
      "3981"
    ]
  },
  {
    "statement": "Five studies showed uncultivated margins had lower species richness than sown margins.",
